STRING_PATCHES = (
    # Прибираємо 3D-учня та його «підлогу», Сонячну систему ставимо по центру кадру.
    ("scene.add(student);", "scene.add(student);student.visible=false;"),
    ("floor.rotation.x=-Math.PI/2;", "floor.visible=false;floor.rotation.x=-Math.PI/2;"),
    ("solarSystem.position.set(-.58,1.58,-1.08)", "solarSystem.position.set(0,1.45,-1.08)"),
    ("solarSystem.scale.setScalar(.88)", "solarSystem.scale.setScalar(1.45)"),
    ("sunLight.position.set(-.58,1.58,-.5)", "sunLight.position.set(0,1.45,-.5)"),
)

HOME_PATCHES = (
    ("Привіт,<br>досліднику!", "Зрозуміло.<br><em>Крок за кроком.</em>"),
    ("Займай своє місце в першому ряду. Тут кожна тема стає зрозумілою пригодою — крок за кроком, у твоєму темпі.", "Предмети, теми, приклади й контрольні для учнів 5–11 класів. Навчайся у своєму темпі та відкривай нове щодня."),
    ("Почати навчання", "Відкривай · Розумій · Практикуй"),
    ("Анімований 3D-учень махає рукою та тримає синю книжку", "Об’ємна 3D-сцена Сонячної системи з планетами на орбітах"),
    ('<span class="fallback-student">🧑‍🎓</span><span class="fallback-wave">👋</span><span class="fallback-book">📘</span>', ""),
)


def apply_cosmic_theme(app, show_page):
    module = sys.modules.get(getattr(show_page, "__module__", ""))
    shell = getattr(module, "SHELL", None)
    if isinstance(shell, str) and 'id="cosmic-theme"' not in shell:
        for old, new in STRING_PATCHES:
            if shell.count(old) == 1:
                shell = shell.replace(old, new)
        if "</head>" in shell:
            shell = shell.replace("</head>", THEME_CSS + "</head>", 1)
        shell = shell.replace('content="#f7f7f2"', 'content="#050a14"')
        module.SHELL = shell

    @app.after_request
    def clean_home(response):
        if request.path == "/" and response.status_code == 200 and response.mimetype == "text/html" and not response.direct_passthrough:
            html = response.get_data(as_text=True)
            for old, new in HOME_PATCHES:
                html = html.replace(old, new)
            response.set_data(html)
        return response
